// ============================================================
// Format AI response for Instagram DM
// ============================================================

const aiOutput = $json.output || 'Вибачте, сталася помилка. Спробуйте ще раз.';
const prepareData = $('Prepare Context').first().json;
const senderId = prepareData.senderId;
const accessToken = prepareData.accessToken;

// Truncate if too long for Instagram (max ~1000 chars)
let replyText = aiOutput;
if (replyText.length > 950) {
  replyText = replyText.substring(0, 947) + '...';
}

return [{
  json: {
    senderId: senderId,
    messagePayload: { text: replyText },
    accessToken: accessToken
  }
}];
